import Database from "better-sqlite3";
import path from "path";

export interface Message {
  room: string;
  seq: number;
  user: string;
  text: string;
  ts: number;
}

type Listener = (msg: Message) => void;

class Broker {
  private listeners = new Map<string, Set<Listener>>();

  subscribe(room: string, listener: Listener): () => void {
    if (!this.listeners.has(room)) {
      this.listeners.set(room, new Set());
    }
    this.listeners.get(room)!.add(listener);

    return () => {
      const roomListeners = this.listeners.get(room);
      if (roomListeners) {
        roomListeners.delete(listener);
        if (roomListeners.size === 0) {
          this.listeners.delete(room);
        }
      }
    };
  }

  publish(room: string, msg: Message) {
    const roomListeners = this.listeners.get(room);
    if (roomListeners) {
      for (const listener of roomListeners) {
        try {
          listener(msg);
        } catch (err) {
          console.error("Error in listener:", err);
        }
      }
    }
  }

  getSubscriberCount(room: string): number {
    return this.listeners.get(room)?.size || 0;
  }
}

// Support hot-reloading in Vite without losing DB connection or broker state
const globalObj = globalThis as any;

if (!globalObj.__db) {
  const dbPath = path.join(process.cwd(), "chat.db");
  const db = new Database(dbPath);
  db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      room TEXT,
      seq INTEGER,
      user TEXT,
      text TEXT,
      ts INTEGER,
      PRIMARY KEY (room, seq)
    );
    CREATE INDEX IF NOT EXISTS idx_messages_room_seq ON messages (room, seq);
  `);
  globalObj.__db = db;
}

if (!globalObj.__broker) {
  globalObj.__broker = new Broker();
}

export const db = globalObj.__db as any;
export const broker = globalObj.__broker as Broker;

import type { RequestHandler } from "@builder.io/qwik-city";
import { db, broker } from "../../../../lib/db";

export const onPost: RequestHandler = async (event) => {
  const { params, parseBody, json } = event;

  // 1. Validate room parameter
  const room = params.room;
  const roomRegex = /^[A-Za-z0-9_-]+$/;
  if (!room || !roomRegex.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  // 2. Parse and validate body
  let body: any;
  try {
    body = await parseBody();
  } catch (err) {
    return json(400, { error: "Malformed JSON body" });
  }

  if (!body || typeof body !== "object") {
    return json(400, { error: "Request body must be a JSON object" });
  }

  const { user, text } = body;
  if (typeof user !== "string" || typeof text !== "string") {
    return json(400, { error: "user and text must be strings" });
  }

  const trimmedUser = user.trim();
  const trimmedText = text.trim();

  if (trimmedUser.length < 1 || trimmedUser.length > 64) {
    return json(400, { error: "user must be between 1 and 64 characters after trimming" });
  }

  if (trimmedText.length < 1 || trimmedText.length > 2000) {
    return json(400, { error: "text must be between 1 and 2000 characters after trimming" });
  }

  // 3. Assign seq and ts atomically, persist to SQLite
  const ts = Date.now();
  let seq: number;

  try {
    const insertTx = db.transaction(() => {
      const row = db.prepare(
        "SELECT COALESCE(MAX(seq), 0) + 1 AS nextSeq FROM messages WHERE room = ?"
      ).get(room) as { nextSeq: number };
      const nextSeq = row.nextSeq;

      db.prepare(
        "INSERT INTO messages (room, seq, user, text, ts) VALUES (?, ?, ?, ?, ?)"
      ).run(room, nextSeq, trimmedUser, trimmedText, ts);

      return nextSeq;
    });

    seq = insertTx();
  } catch (err: any) {
    return json(500, { error: err.message || "Failed to persist message" });
  }

  // 4. Construct message object containing exactly the required keys
  const message = {
    room,
    seq,
    user: trimmedUser,
    text: trimmedText,
    ts,
  };

  // 5. Broadcast to live subscribers
  broker.publish(room, message);

  // 6. Respond HTTP 201
  return json(201, message);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { db, broker, type Message } from "../../../../lib/db";

export const onGet: RequestHandler = async (event) => {
  const { params, headers, status, getWritableStream, request, signal, json } = event;

  // 1. Validate room parameter
  const room = params.room;
  const roomRegex = /^[A-Za-z0-9_-]+$/;
  if (!room || !roomRegex.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  // 2. Set headers for SSE stream
  headers.set("Content-Type", "text/event-stream");
  headers.set("Cache-Control", "no-cache, no-transform");
  headers.set("Connection", "keep-alive");
  headers.set("X-Accel-Buffering", "no");

  status(200);

  // 3. Get writable stream
  const stream = getWritableStream();
  const writer = stream.getWriter();
  const encoder = new TextEncoder();

  let closed = false;

  // 4. Parse Last-Event-ID header
  const lastEventIdHeader = request.headers.get("last-event-id");
  let L: number | null = null;
  if (lastEventIdHeader !== null) {
    const parsed = parseInt(lastEventIdHeader, 10);
    if (!isNaN(parsed)) {
      L = parsed;
    }
  }

  // 5. Setup subscription and queue
  const queue: Message[] = [];
  let replaying = true;
  let maxSeq = L !== null ? L : 0;

  const unsubscribe = broker.subscribe(room, (msg) => {
    if (replaying) {
      queue.push(msg);
    } else {
      if (msg.seq > maxSeq) {
        sendEvent(msg);
        maxSeq = msg.seq;
      }
    }
  });

  const cleanup = () => {
    if (closed) return;
    closed = true;
    unsubscribe();
    clearInterval(keepAliveInterval);
    try {
      writer.close();
    } catch (e) {}
  };

  signal.addEventListener("abort", cleanup);

  function sendEvent(msg: Message) {
    if (closed) return;
    const jsonStr = JSON.stringify({
      room: msg.room,
      seq: msg.seq,
      user: msg.user,
      text: msg.text,
      ts: msg.ts,
    });
    const chunk = `id: ${msg.seq}\nevent: message\ndata: ${jsonStr}\n\n`;
    writer.write(encoder.encode(chunk)).catch(() => {
      cleanup();
    });
  }

  // Send a keep-alive comment periodically to detect disconnected clients
  const keepAliveInterval = setInterval(() => {
    if (closed) return;
    writer.write(encoder.encode(":\n\n")).catch(() => {
      cleanup();
    });
  }, 15000);

  // 6. Query history
  let history: Message[] = [];
  try {
    if (L !== null) {
      history = db.prepare(
        "SELECT room, seq, user, text, ts FROM messages WHERE room = ? AND seq > ? ORDER BY seq ASC"
      ).all(room, L) as Message[];
    } else {
      const rows = db.prepare(
        "SELECT room, seq, user, text, ts FROM messages WHERE room = ? ORDER BY seq DESC LIMIT 50"
      ).all(room) as Message[];
      history = rows.reverse();
    }
  } catch (err) {
    console.error("Failed to query history:", err);
    cleanup();
    return;
  }

  // 7. Emit history
  for (const msg of history) {
    if (msg.seq > maxSeq) {
      sendEvent(msg);
      maxSeq = msg.seq;
    }
  }

  // 8. Emit buffered queue
  for (const msg of queue) {
    if (msg.seq > maxSeq) {
      sendEvent(msg);
      maxSeq = msg.seq;
    }
  }

  // 9. Transition to live stream
  replaying = false;
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { broker } from "../../../../lib/db";

export const onGet: RequestHandler = async (event) => {
  const { params, json } = event;

  // 1. Validate room parameter
  const room = params.room;
  const roomRegex = /^[A-Za-z0-9_-]+$/;
  if (!room || !roomRegex.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  // 2. Get subscriber count from the in-memory broker
  const count = broker.getSubscriberCount(room);

  // 3. Respond HTTP 200 with JSON
  return json(200, {
    room,
    subscribers: count,
  });
};

